package verify

import (
	"github.com/MateusMoutinhoOrg/Agnos/sandbox/api"
	"github.com/MateusMoutinhoOrg/Agnos/sandbox/internal/stagedfs"
	"github.com/MateusMoutinhoOrg/Agnos/sandbox/internal/utils"
)

// generatedRoots are the trees a generated Go file is written into.
var generatedRoots = []string{"sandbox", "adapters", "cmd"}

// CheckGenerated enforces that every Go file named with utils.GeneratedPrefix
// opens with the line the build writes on top of it — `// Code generated by
// <generator>. DO NOT EDIT.` — so the prefix never names a file the project
// wrote by hand: the build would write over it, and every reader takes it for
// one the build owns.
func CheckGenerated(sandbox *api.Sandbox, io *stagedfs.StagedFS) []string {
	var violations []string

	for _, root := range generatedRoots {
		for _, file := range goFilesUnder(sandbox, io, root) {
			if !utils.IsGeneratedFile(sandbox, file) {
				continue
			}
			content, err := io.ReadFile(file)
			if err != nil {
				continue
			}
			first := sandbox.Deps.StringsDeps.Split(string(content), "\n")[0]
			if sandbox.Deps.StringsDeps.HasPrefix(first, "// Code generated ") && sandbox.Deps.StringsDeps.HasSuffix(first, " DO NOT EDIT.") {
				continue
			}
			violations = append(violations, file+" is named "+utils.GeneratedPrefix+"* but does not open with `"+
				sandbox.Deps.StringsDeps.TrimSpace(utils.GeneratedHeader(sandbox))+"`: the prefix is for a file the build rewrites whole —"+
				" rename a hand-written one without it")
		}
	}

	return violations
}
